CREATE TABLE a(
 NAME VARCHAR(20),
 score INT
);
CREATE TABLE b(
 NAME VARCHAR(20),
 score INT
);
INSERT INTO A VALUES('a',10),('b',20),('c',30);
INSERT INTO B VALUES('a',10),('b',20),('d',40);

-- 合并结果集去重

sql
SELECT * FROM a
UNION
SELECT * FROM b

-- 只合并不去重

SELECT * FROM a

UNION ALL

SELECT * FROM b;

-- 注意: 被合并的表的列名可以不同，但列数和类型必须相同！

